    for round in 0..n
        invariant done.len() == n,
    {
        let mut u: usize = n;
        let mut k: usize = n;
        while k > 0
            invariant k <= n && u <= n,
            decreases k,
        {
            k = k - 1;
            if k < want.len() && want[k] && !done[k] {
                u = k;
            }
        }
        if u == n {
            break;
        }
        done[u] = true;
